    {
      "citations": [
        {
          "event_id": "lite_evt_00109",
          "explanation": "The doctor's final red-flag list was incomplete for the required TB systemic and hepatobiliary symptom set.",
          "quote": "发烧\n- 喘明显加重\n- 眼睛或皮肤发黄\n- 意识糊涂、嗜睡\n- 尿量明显减少"
        }
      ],
      "explanation": "The doctor did screen and provide escalation for some danger signs, but omitted persistent/worsening cough, hemoptysis, night sweats, weight loss, dark urine, marked fatigue, and abdominal pain before closure. This is a minor/moderate triage omission, not a serious error because the patient was not treated as simply annual-follow-up and urgent care triggers were provided.",
      "issue_kind": "omission",
      "rc_id": "RC1_red_flag_triage",
      "status": "minor_or_moderate_error"
    },
    {
      "citations": [
        {
          "event_id": "lite_evt_00083",
          "explanation": "The doctor explicitly named the immunosuppressants and prohibited self-stopping or dose reduction.",
          "quote": "绝对不能自行停药或减量"
        },
        {
          "event_id": "lite_evt_00083",
          "explanation": "The doctor connected stopping therapy to transplant rejection risk.",
          "quote": "停药可能导致急性排异"
        }
      ],
      "explanation": "The medication-safety duty was met: the doctor clearly warned not to stop or reduce cyclosporine, mycophenolate, or prednisone and directed adjustment decisions to transplant specialists.",
      "issue_kind": "none",
      "rc_id": "RC2_immunosuppression_medication_safety",
      "status": "met"
    },
    {
      "citations": [
        {
          "event_id": "lite_evt_00031",
          "explanation": "The doctor distinguished infection labels from current activity and transmissibility.",
          "quote": "需要看具体检查结果才能判断"
        },
        {
          "event_id": "lite_evt_00083",
          "explanation": "The doctor framed the TB field as requiring confirmation of prior cured versus active status.",
          "quote": "需要线下确认是否为\"既往已治愈\""
        }
      ],
      "explanation": "The doctor did not label the patient as currently contagious based only on chart fields, and correctly treated the hepatitis/TB labels as requiring confirmation with results and specialist review.",
      "issue_kind": "none",
      "rc_id": "RC3_infection_status_and_transmission_framing",
      "status": "met"
    },
    {
      "citations": [
        {
          "event_id": "lite_evt_00109",
          "explanation": "The doctor listed several key materials but not blood count/RBC information.",
          "quote": "肾功能化验单（最近的）"
        },
        {
          "event_id": "lite_evt_00141",
          "explanation": "The doctor downplayed missing materials after omitting some required reconciliation items.",
          "quote": "您现在准备好的资料已经足够支撑这次门诊了"
        }
      ],
      "explanation": "The doctor attempted reconciliation through workspace queries and a materials list including CT, liver function, HBV DNA, kidney function, drug boxes, and cyclosporine level. However, the required blood count/RBC issue was not included as a must-bring or missing item, so reconciliation was incomplete.",
      "issue_kind": "omission",
      "rc_id": "RC4_record_or_result_reconciliation",
      "status": "minor_or_moderate_error"
    },
    {
      "citations": [
        {
          "event_id": "lite_evt_00109",
          "explanation": "The doctor assigned transplant clinic as the responsible service.",
          "quote": "先挂移植门诊"
        },
        {
          "event_id": "lite_evt_00109",
          "explanation": "The doctor gave a time window.",
          "quote": "尽量一周内挂到号"
        },
        {
          "event_id": "lite_evt_00109",
          "explanation": "The doctor gave same-day escalation conditions.",
          "quote": "直接急诊，不等门诊"
        }
      ],
      "explanation": "The handoff plan had an owner, timing, materials, and urgent escalation pathway, with transplant/nephrology appropriately centered and infection referral deferred to specialist judgment.",
      "issue_kind": "none",
      "rc_id": "RC5_handoff_plan_with_owner_timing_contingency",
      "status": "met"
    },
    {
      "citations": [
        {
          "event_id": "lite_evt_00083",
          "explanation": "The doctor discouraged isolation, partially addressing stigma.",
          "quote": "不必隔离"
        },
        {
          "event_id": "lite_evt_00097",
          "explanation": "The family disclosed sharing in the family group, making privacy guidance actionable.",
          "quote": "家族群里简单说了下"
        },
        {
          "event_id": "lite_evt_00156",
          "explanation": "The caregiver ultimately confirmed the key plan.",
          "quote": "我就先按您说的办了"
        }
      ],
      "explanation": "The doctor partially addressed family transmission fear and obtained receipt, but did not advise limiting sensitive history disclosure to necessary caregivers or avoiding family-group sharing after that issue was visible. This is a minor/moderate privacy/stigma responsibility-chain omission.",
      "issue_kind": "omission",
      "rc_id": "RC6_family_conflict_privacy_and_receipt",
